module barrel_shifter #(parameter data_width=16,shift_bits_width=4)(input [data_width-1:0] data_in,input [shift_bits_width-1:0] shift_bits,input left_right,rotate_left_right,output reg [data_width-1:0] data_out);
integer amount;
always @* begin
 amount=shift_bits%data_width;
 if(!rotate_left_right)data_out=left_right?(data_in<<shift_bits):(data_in>>shift_bits);
 else if(amount==0)data_out=data_in;
 else if(left_right)data_out=(data_in<<amount)|(data_in>>(data_width-amount));
 else data_out=(data_in>>amount)|(data_in<<(data_width-amount));
end
endmodule

module signed_unsigned_comparator #(parameter WIDTH=5)(input [WIDTH-1:0] i_A,i_B,input i_enable,i_mode,output reg o_greater,o_less,o_equal);
always @* begin
 o_greater=0;o_less=0;o_equal=0;
 if(i_enable)begin
 o_equal=i_A==i_B;
 if(i_mode)begin o_greater=$signed(i_A)>$signed(i_B);o_less=$signed(i_A)<$signed(i_B);end
 else begin o_greater=i_A>i_B;o_less=i_A<i_B;end
 end
end
endmodule

module bcd_counter(input clk,rst,output reg [3:0] ms_hr,ls_hr,ms_min,ls_min,ms_sec,ls_sec);
always @(posedge clk or posedge rst)begin
 if(rst)begin ms_hr<=0;ls_hr<=0;ms_min<=0;ls_min<=0;ms_sec<=0;ls_sec<=0;end
 else if(ls_sec!=9)ls_sec<=ls_sec+1'b1;
 else begin ls_sec<=0;
 if(ms_sec!=5)ms_sec<=ms_sec+1'b1;
 else begin ms_sec<=0;
 if(ls_min!=9)ls_min<=ls_min+1'b1;
 else begin ls_min<=0;
 if(ms_min!=5)ms_min<=ms_min+1'b1;
 else begin ms_min<=0;
 if(ms_hr==2 && ls_hr==3)begin ms_hr<=0;ls_hr<=0;end
 else if(ls_hr==9)begin ls_hr<=0;ms_hr<=ms_hr+1'b1;end
 else ls_hr<=ls_hr+1'b1;
 end end end end
end
endmodule

module binary_to_bcd(input logic [7:0] binary_in,output logic [11:0] bcd_out);
reg [19:0] shift_reg;integer i,j;
always @*begin
 shift_reg={12'd0,binary_in};
 for(i=0;i<8;i=i+1)begin
 for(j=8;j<20;j=j+4)if(shift_reg[j+:4]>=5)shift_reg[j+:4]=shift_reg[j+:4]+4'd3;
 shift_reg=shift_reg<<1;
 end
 bcd_out=shift_reg[19:8];
end
endmodule

module hamming_code_receiver(input [7:0] data_in,output reg [3:0] data_out);
reg [2:0] syndrome;reg [7:0] corrected;
always @*begin
 syndrome={data_in[4]^data_in[5]^data_in[6]^data_in[7],data_in[2]^data_in[3]^data_in[6]^data_in[7],data_in[1]^data_in[3]^data_in[5]^data_in[7]};
 corrected=data_in;if(syndrome!=0)corrected[syndrome]=~corrected[syndrome];
 data_out={corrected[7:5],corrected[3]};
end
endmodule

module moving_average(input clk,reset,input [11:0] data_in,output reg [11:0] data_out);
reg [11:0] samples[0:7];reg [2:0] ptr;reg [14:0] sum;integer i;
wire [14:0] next_sum=sum-{3'b0,samples[ptr]}+{3'b0,data_in};
always @(posedge clk)begin
 if(reset)begin ptr<=0;sum<=0;data_out<=0;for(i=0;i<8;i=i+1)samples[i]<=0;end
 else begin samples[ptr]<=data_in;ptr<=ptr+1'b1;sum<=next_sum;data_out<=next_sum[14:3];end
end
endmodule

module clock_divider(input clk,rst_n,input [1:0] sel,output reg clk_out);
reg [2:0] count;
always @(posedge clk or negedge rst_n)begin
 if(!rst_n)begin count<=0;clk_out<=0;end
 else case(sel)
 0:begin count<=0;clk_out<=~clk_out;end
 1:if(count==1)begin count<=0;clk_out<=~clk_out;end else count<=count+1'b1;
 2:if(count==3)begin count<=0;clk_out<=~clk_out;end else count<=count+1'b1;
 default:begin count<=0;clk_out<=0;end
 endcase
end
endmodule

module cdc_pulse_synchronizer (
    input  logic src_clock,   // Source Clock Domain
    input  logic des_clock,   // Destination Clock Domain
    input  logic rst_in,      // Reset
    input  logic src_pulse,   // Source Pulse
    output logic des_pulse    // Destination Pulse
);

    logic pls_toggle;      
    logic pls_toggle_synca;
    logic pls_toggle_syncc;

    //--------------------------------------------------
    //   Toggle Flop Circuit
    //---------------------------------------------------

    always_ff @(posedge src_clock or posedge rst_in) begin
        if (rst_in) begin
            pls_toggle <= 1'b0;
        end else if (src_pulse) begin
            pls_toggle <= ~pls_toggle;
        end
    end

    //--------------------------------------------------
    //   Double Flop Bit Synchronizer
    //---------------------------------------------------

    always_ff @(posedge des_clock or posedge rst_in) begin
        if (rst_in) begin
            pls_toggle_synca <= 1'b0;
        end else begin
            pls_toggle_synca <= pls_toggle;
        end
    end

    //--------------------------------------------------
    //   Delay Logic of Output signal
    //---------------------------------------------------

    always_ff @(posedge des_clock or posedge rst_in) begin
        if (rst_in) begin
            pls_toggle_syncc <= 1'b0;
        end else begin
            pls_toggle_syncc <= pls_toggle_synca;
        end
    end

    //--------------------------------------------------
    //   Assign Statement for posedge and negedge detection
    //---------------------------------------------------

    assign des_pulse = pls_toggle_syncc ^ pls_toggle_synca; 
endmodule

module radix2_div(
    input            clk,
    input            rst_n,
    input            start,
    input      [7:0] dividend,
    input      [7:0] divisor,
    output reg [7:0] quotient,
    output reg [7:0] remainder,
    output reg       done
);

    reg [7:0] rem;
    reg [3:0] bit_counter;
    reg [7:0] divisor_reg;
    reg       busy;

    // Normal, correct shift and compare logic
    wire [8:0] shifted_rem = {rem, dividend[bit_counter]};
    wire       bit_set     = shifted_rem >= {1'b0, divisor_reg};
    wire [8:0] next_rem    = bit_set ? (shifted_rem - {1'b0, divisor_reg}) : shifted_rem;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n)
            quotient <= 8'd0;
        else if (start && !busy) begin
            if (divisor == 8'd0)
                quotient <= 8'hFF;
            else
                quotient <= 8'd0;
        end
        else if (busy) begin
            quotient[bit_counter] <= bit_set;
        end
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n)
            rem <= 8'd0;
        else if (start && !busy)
            rem <= 8'd0;
        else if (busy)
            rem <= next_rem[7:0];
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n)
            remainder <= 8'd0;
        else if (start && !busy && divisor == 8'd0)
            remainder <= 8'hFF;
        else if (busy && bit_counter == 4'd0) begin
            remainder <= next_rem[7:0];
        end
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n)
            bit_counter <= 4'd0;
        else if (start && !busy) begin
            if (divisor != 8'd0)
                bit_counter <= 4'd7;  // Start from MSB
        end
        else if (busy && bit_counter != 4'd0) begin
            bit_counter <= bit_counter - 4'd1; // Normal decrement
        end
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n)
            divisor_reg <= 8'd0;
        else if (start && !busy && divisor != 8'd0)
            divisor_reg <= divisor;
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n)
            done <= 1'b0;
        else if (start && !busy) begin
            if (divisor == 8'd0)
                done <= 1'b1;
            else
                done <= 1'b0;
        end
        else if (busy && bit_counter == 4'd0)
            done <= 1'b1;
        else
            done <= 1'b0;
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n)
            busy <= 1'b0;
        else if (start && !busy) begin
            if (divisor != 8'd0)
                busy <= 1'b1;
            else
                busy <= 1'b0;
        end
        else if (busy && bit_counter == 4'd0)
            busy <= 1'b0;
    end

endmodule
